mapper.select:
select
mn.*,
c1.C_Name as se_unit_name
from sporadic_settlement mn
left join SYS_Company c1 on c1.C_Id=mn.se_unit_id

    
        and mn.se_p_name like concat('%',#{params.sePName},'%')
    
    
        and mn.se_unit_id = #{params.seUnitId}
    
    
        and c1.C_Name like concat('%',#{params.seUnitName},'%')
    
    
        and mn.se_price = #{params.sePrice}
    
    
        and mn.se_price >= #{params.sePriceStart}
    
    
        and mn.se_price <= #{params.sePriceEnd}
    
    
        and mn.se_audit_time = #{params.seAuditTime}
    
    
        and mn.se_audit_time >= #{params.seAuditTimeStart}
    
    
        and mn.se_audit_time <= #{params.seAuditTimeEnd}
    
    
        and mn.se_p_number like concat('%',#{params.sePNumber},'%')
    
    
        and mn.state = #{params.state}
    
    
        and not exists(select 1 from sporadic_payments_dtl spd join sporadic_payments sp on sp.id = spd.sp_p_did where spd.sp_d_id = mn.id and sp.state != 3)
    
    
        AND NOT EXISTS (
        SELECT 1
        FROM sporadic_settlement_dtl ssd
        JOIN Maintenance_Record mr ON mr.mr_Id = ssd.mr_id
        WHERE ssd.se_id = mn.id
        AND mr.mr_category != #{params.mrCategory}
        )
        AND EXISTS (SELECT 1 FROM sporadic_settlement_dtl WHERE se_id = mn.id)
    

order by mn.create_time desc

SELECT
IF(EXISTS(
SELECT 1
FROM sporadic_settlement_dtl mn
JOIN sporadic_settlement sse
ON mn.se_id = sse.id
WHERE mn.mr_id IN

    #{mrId}


    AND mn.se_id != #{seId}

AND sse.state != 3
), 1, 0) as conflict;

SELECT CASE WHEN EXISTS ( SELECT 1 FROM sporadic_settlement_dtl mn JOIN sporadic_settlement sse ON mn.se_id = sse.id WHERE mn.mr_id IN
#{mrId}
AND mn.se_id != #{seId}
AND sse.state != 3 ) THEN 1 ELSE 0 END AS conflict FROM dual

select mn.* from maintenance_finance mn WHERE 1=1
AND mn.mr_id IN
#{mrId}
